            continue
        remaining = route[:]
        seq = []
        current = depot_coord
        while remaining:
            best = None
            best_key = None
            for cid in remaining:
                key = (dist(current, coords[cid]), dist(coords[cid], depot_coord), cid)
                if best is None or key < best_key:
                    best = cid
                    best_key = key
            seq.append(best)
            current = coords[best]
            remaining.remove(best)
        routes[idx] = seq

    # Repair/merge lightly: move suffix customers to fill earlier slack if beneficial
    # (kept deterministic and capacity-feasible)
    i = 0
    while i < len(routes):
        j = i + 1
        while j < len(routes):
            changed = False
            ri = routes[i]
            rj = routes[j]
            li = route_load(ri)
            lj = route_load(rj)
            # Try moving first customer of rj into ri if feasible and closer than keeping in rj
            if rj:
                cid = rj[0]
                if li + demands[cid] <= capacity:
                    if not ri:
                        ri.append(cid)
                        rj.pop(0)
                        changed = True
                    else:
                        end_i = coords[ri[-1]]
                        start_rj = coords[cid]
                        old_cost = dist(coords[ri[-1]], depot_coord) + dist(depot_coord, start_rj)
                        new_cost = dist(end_i, start_rj)
                        if new_cost <= old_cost:
                            ri.append(cid)
                            rj.pop(0)
                            changed = True
            if changed and not rj:
                routes.pop(j)
            else:
                j += 1
        i += 1

    # Append infeasible customers as singleton routes if any (cannot satisfy capacity otherwise)
    for cid in infeasible:
        routes.append([cid])

    return routes
